// ── BORDERS ───────────────────────────────────────────────
const noBrd = { style: BorderStyle.NIL, size: 0, color: WHITE };
const noB   = { top:noBrd, bottom:noBrd, left:noBrd, right:noBrd };
const thin  = (c=BRDR) => ({ style:BorderStyle.SINGLE, size:4, color:c });
const thinB = { top:thin(), bottom:thin(), left:thin(), right:thin() };

// ── HELPERS ───────────────────────────────────────────────
const cm  = { top:80,  bottom:80,  left:120, right:120 };
const cmL = { top:120, bottom:120, left:200, right:200 };
const t   = (text, opts={}) => new TextRun({ text, font:'Tahoma', size:18, color:TEXT, ...opts });
const p   = (children, opts={}) => new Paragraph({ children, ...opts });
const ep  = (sz=6) => p([t('', {size:sz})]);
const pb  = () => p([new PageBreak()]);

// ── SECTION HEADER BAR ────────────────────────────────────
function sectionBar(title, badge) {
  const tw = badge ? CW - 2400 : CW;
  const cells = [
    new TableCell({
      width:{size:tw,type:WidthType.DXA},
      shading:{fill:NAVY,type:ShadingType.CLEAR},
      borders:noB, margins:cmL,
      children:[p([t(title.toUpperCase(),{bold:true,color:WHITE,size:30})])]
    })
  ];
  if (badge) cells.push(new TableCell({
    width:{size:2400,type:WidthType.DXA},
    shading:{fill:GOLD,type:ShadingType.CLEAR},
    borders:noB, margins:cmL, verticalAlign:VerticalAlign.CENTER,
    children:[p([t(badge,{bold:true,color:NAVY,size:20})],{alignment:AlignmentType.CENTER})]
  }));
  return new Table({
    width:{size:CW,type:WidthType.DXA},
    columnWidths: badge ? [tw,2400] : [CW],
    rows:[new TableRow({children:cells})]
  });
}

// ── FEEDBACK TABLE ────────────────────────────────────────
function feedbackLabelRow() {
  return new TableRow({
    children: ['Criterion','Score','Descriptor','Notes'].map((lbl,i) =>
      new TableCell({
        width:{size:[FC1,FC2,FC3,FC4][i],type:WidthType.DXA},
        shading:{fill:NAVY2,type:ShadingType.CLEAR},
        borders:thinB, margins:cm,
        children:[p([t(lbl,{bold:true,color:GOLD,size:17})],
          {alignment: i===1 ? AlignmentType.CENTER : AlignmentType.LEFT})]
      })
    )
  });
}
function criteriaHeader(name, score) {
  return new TableRow({
    children:[new TableCell({
      columnSpan:4,
      width:{size:CW,type:WidthType.DXA},
      shading:{fill:'EAF0F8',type:ShadingType.CLEAR},
      borders:{
        top:thin(NAVY), bottom:thin(NAVY),
        left:{style:BorderStyle.SINGLE,size:20,color:NAVY},
        right:noB.right
      },
      margins:{top:120,bottom:120,left:200,right:160},
      children:[p([
        t(name.toUpperCase(),{bold:true,color:NAVY,size:22}),
        t('   '+String(score),{bold:true,color:NAVY2,size:26})
      ])]
    })]
  });
}
function subRow(criterion, score, descriptor, notes) {
  return new TableRow({
    children:[
      new TableCell({
        width:{size:FC1,type:WidthType.DXA},
        borders:thinB, margins:cm, verticalAlign:VerticalAlign.CENTER,
        children:[p([t(criterion,{bold:true,color:NAVY,size:18})])]
      }),
      new TableCell({
        width:{size:FC2,type:WidthType.DXA},
        borders:thinB, margins:cm,
        shading:{fill:LIGHT,type:ShadingType.CLEAR},
        verticalAlign:VerticalAlign.CENTER,
        children:[p([t(String(score),{bold:true,color:NAVY,size:28})],{alignment:AlignmentType.CENTER})]
      }),
      new TableCell({
        width:{size:FC3,type:WidthType.DXA},
        borders:thinB, margins:cm, verticalAlign:VerticalAlign.CENTER,
        children:[p([t(descriptor||'',{size:18,color:TEXT})])]
      }),
      new TableCell({
        width:{size:FC4,type:WidthType.DXA},
        borders:thinB, margins:cm, verticalAlign:VerticalAlign.CENTER,
        shading:{fill:notes?NOTES:WHITE,type:ShadingType.CLEAR},
        children:[notes
          ? p([t('Ghi chú: ',{bold:true,color:NAVY,size:17}),t(notes,{size:17,color:MUTED,italics:true})])
          : p([t('',{size:18})])
        ]
      })
    ]
  });
}
function feedbackBlock(criteria) {
  const items = [
    new Table({
      width:{size:CW,type:WidthType.DXA},
      columnWidths:[FC1,FC2,FC3,FC4],
      rows:[feedbackLabelRow()]
    })
  ];
  criteria.forEach(c => {
    items.push(ep(8));
    items.push(new Table({
      width:{size:CW,type:WidthType.DXA},
      columnWidths:[FC1,FC2,FC3,FC4],
      rows:[
        criteriaHeader(c.name, c.score),
        ...c.rows.map(r => subRow(r[0],r[1],r[2],r[3]))
      ]
    }));
  });
  return items;
}

// ── CHECKBOX GRID ─────────────────────────────────────────
function checkboxGrid(wrongQs) {
  const base = Math.floor(CW/10), rem = CW - base*10;
  const cws  = Array(10).fill(base); cws[9] += rem;
  const rows = [];
  for (let r=0; r<4; r++) {
    const cells = [];
    for (let c=0; c<10; c++) {
      const q = r*10+c+1;
      const isWrong = wrongQs.includes(q);
      cells.push(new TableCell({
        width:{size:cws[c],type:WidthType.DXA},
        borders:thinB, margins:{top:40,bottom:40,left:40,right:40},
        shading:{fill:isWrong?'FEF2F2':WHITE,type:ShadingType.CLEAR},
        verticalAlign:VerticalAlign.CENTER,
        children:[
          p([t('Q'+q,{size:13,color:isWrong?'991B1B':MUTED})],{alignment:AlignmentType.CENTER}),
          p([t(isWrong?'✗':'',{size:22,bold:true,color:'991B1B'})],{alignment:AlignmentType.CENTER})
        ]
      }));
    }
    rows.push(new TableRow({height:{value:700,rule:'atLeast'},children:cells}));
  }
  return new Table({width:{size:CW,type:WidthType.DXA},columnWidths:cws,rows});
}

// ── NEW: PAYLOAD ADAPTERS ─────────────────────────────────

// Convert answerMap (40 booleans: true=correct) to array of wrong Q numbers
function answerMapToWrong(answerMap) {
  if (!answerMap || !Array.isArray(answerMap)) return [];
  return answerMap.reduce((acc, correct, i) => {
    if (!correct) acc.push(i + 1);
    return acc;
  }, []);
}

